templates.message:
{assign "displayTotalToday" true}
<p><strong>Order Information</strong></p>
<p>Order ID: {$order_id}<br />
Order Number: {$order_number}<br />
Date/Time: {$order_date}<br />
Invoice Number: {if $custom_invoice_number}{$custom_invoice_number}{else}{$invoice_id}{/if}<br />
Payment Method: {$order_payment_method}</p>
<p><strong>Customer Information</strong></p>
<p>Customer ID: {$client_id}<br />
Name: {$client_first_name} {$client_last_name}<br />
Email: {$client_email}<br />
Company: {$client_company_name}<br />
Address 1: {$client_address1}<br />
Address 2: {$client_address2}<br />
City: {$client_city}<br />
State: {$client_state}<br />
Postcode: {$client_postcode}<br />
Country: {$client_country}<br />
Phone Number: {$client_phonenumber}</p>
<p><strong>Order Items</strong></p>
<p>{foreach $order_items_array as $key => $value}
    {if $value.service}
        Product/Service: {$value.service}<br>
        {if !empty($value.domain)}Domain: {$value.domain}<br>{/if}
        {if !empty($value.extra)}{foreach $value.extra as $extra}{$extra}<br>{/foreach}{/if}
        First Payment Amount: {$value.firstPayment}<br>
        {if !empty($value.recurringPayment)}Recurring Amount: {$value.recurringPayment}<br>{/if}
        Billing Cycle: {$value.cycle}<br>
        {if $value.qty}
            Quantity: {$value.qty}<br>
            Total: {$value.totalDue}<br>
        {/if}<br>
    {elseif !empty($value.domain)}
        Domain Action: {$value.type}<br>
        Domain: {$value.domain}<br>
        {if !empty($value.firstPayment)}First Payment Amount: {$value.firstPayment}<br>{/if}
        {if !empty($value.recurringPayment)}Recurring Amount: {$value.recurringPayment}<br>{/if}
        Registration Period: {$value.registrationPeriod}<br>
        {if $value.dnsManagement}DNS Management<br>{/if}
        {if $value.emailForwarding}Email Forwarding<br>{/if}
        {if $value.idProtection}ID Protection<br>{/if}
    {elseif $value.addon}
        {if !empty($value.qty)}{$value.qty} x {/if}Addon: {$value.addon}<br>
        Setup Fee: {$value.setupFee}<br>
        {if !empty($value.recurringPayment)}Recurring Amount: {$value.recurringPayment}<br>{/if}
        Billing Cycle: {$value.cycle}<br>
    {elseif $value.upgrade}
{$value.upgrade}
{$displayTotalToday = false}
{/if}<br>
{/foreach}
{if $displayTotalToday eq true}Total Due Today: {$total_due_today}{/if}</p>
{if $order_notes}<p><strong>Order Notes</strong></p>
<p>{$order_notes}</p>{/if}
<p><strong>ISP Information</strong></p>
<p>IP: {$client_ip}<br />
Host: {$client_hostname}</p><p><a href="{$whmcs_admin_url}orders.php?action=view&id={$order_id}">{$whmcs_admin_url}orders.php?action=view&id={$order_id}</a></p>

{if $newTicket}
    <p>Ticket #<a href="{$whmcs_admin_url}supporttickets.php?action=viewticket&id={$ticket_id}"><strong>{$ticket_tid}</strong></a> has been opened by <strong>{$changer}</strong>.</p>
    <p>
        Client: {$client_name}{if $client_id} #{$client_id}{/if}<br />
        Department: {$ticket_department}<br />
        Subject: {$ticket_subject}<br />
        Priority: {$ticket_priority}
    </p>
    <div class="quoted-content">
        {$newTicket}
    </div>
{else}
    <p>Ticket #<a href="{$whmcs_admin_url}supporttickets.php?action=viewticket&id={$ticket_id}"><strong>{$ticket_tid}</strong></a> {if $newReply || $newNote}has had a new {if $newReply}reply{else}note{/if} posted by{else}has been updated by{/if} <strong>{$changer}</strong>.</p>

    {if $changes}
        <table class="keyvalue-table" style="border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt;">
            <tbody>
                {foreach $changes as $change}
                    <tr>
                        <td>{$change@key}:</td>
                        <td>
                            <span style="background-color:#ffe7e7;text-decoration:line-through;">{$change.old}</span>
                            &nbsp;
                            <span style="background-color:#ddfade;">{$change.new}</span>
                        </td>
                    </tr>
                {/foreach}
            </tbody>
        </table>
    {/if}

    {if $newReply}
        <div class="quoted-content">
            {$newReply}
        </div>
    {/if}

    {if $newNote}
        <div class="quoted-content">
            {$newNote}
        </div>
    {/if}

    {if $newAttachments}{$newAttachments}{/if}
{/if}
<p>
    You can respond to this ticket by simply replying to this email or through the admin area at the url below.
</p>
<p>
    <a href="{$whmcs_admin_url}supporttickets.php?action=viewticket&id={$ticket_id}">
        {$whmcs_admin_url}supporttickets.php?action=viewticket&id={$ticket_id}
    </a>
</p>
